  external ffi.Pointer<ffi.Float> positions;

  external ffi.Pointer<ffi.Float> normals;

  external ffi.Pointer<ffi.Float> tangents;

  external ffi.Pointer<ffi.Float> uvs;

  @ffi.Size()
  external int vertex_count;

  external ffi.Pointer<ffi.Uint32> indices;

  @ffi.Size()
  external int index_count;

  static ffi.Pointer<FyMeshData> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Float> positions,
    required ffi.Pointer<ffi.Float> normals,
    required ffi.Pointer<ffi.Float> tangents,
    required ffi.Pointer<ffi.Float> uvs,
    required int vertex_count,
    required ffi.Pointer<ffi.Uint32> indices,
    required int index_count,
  }) => $allocator<FyMeshData>()
    ..ref.positions = positions
    ..ref.normals = normals
    ..ref.tangents = tangents
    ..ref.uvs = uvs
    ..ref.vertex_count = vertex_count
    ..ref.indices = indices
    ..ref.index_count = index_count;
}

final class FyMeshRenderer extends ffi.Struct {
  @ffi.Uint64()
  external int mesh;

  @ffi.Uint64()
  external int material;

  @ffi.Bool()
  external bool own_color;

  external FyColor color;

  @ffi.Bool()
  external bool cast_shadows;

  @ffi.Bool()
  external bool receive_shadows;
}

final class FyModel extends ffi.Opaque {}

final class FyModelCounts extends ffi.Struct {
  @ffi.Size()
  external int meshes;

  @ffi.Size()
  external int textures;

  @ffi.Size()
  external int materials;

  @ffi.Size()
  external int warnings;

  static ffi.Pointer<FyModelCounts> $allocate(
    ffi.Allocator $allocator, {
    required int meshes,
    required int textures,
    required int materials,
    required int warnings,
  }) => $allocator<FyModelCounts>()
    ..ref.meshes = meshes
    ..ref.textures = textures
    ..ref.materials = materials
    ..ref.warnings = warnings;
}

final class FyQuat extends ffi.Struct {
  @ffi.Float()
  external double x;

  @ffi.Float()
  external double y;

  @ffi.Float()
  external double z;

  @ffi.Float()
  external double w;

  static ffi.Pointer<FyQuat> $allocate(
    ffi.Allocator $allocator, {
    required double x,
    required double y,
    required double z,
    required double w,
  }) => $allocator<FyQuat>()
    ..ref.x = x
    ..ref.y = y
    ..ref.z = z
    ..ref.w = w;
}

final class FyRay extends ffi.Struct {
  external FyVec3 origin;

  external FyVec3 direction;
}

final class FyRayHit extends ffi.Struct {
  @ffi.Uint64()
  external int object;

  external FyVec3 point;

  external FyVec3 normal;

  @ffi.Float()
  external double distance;
}

sealed class FyStatus {
  static const FY_STATUS_OK = 0;
  static const FY_STATUS_NO_OBJECT = 1;
  static const FY_STATUS_NO_COMPONENT = 2;
  static const FY_STATUS_NO_MESH = 3;
  static const FY_STATUS_NO_MATERIAL = 4;
  static const FY_STATUS_IN_USE = 5;
  static const FY_STATUS_INVALID_VALUE = 6;
  static const FY_STATUS_NULL_POINTER = 7;
  static const FY_STATUS_NO_GPU = 8;
  static const FY_STATUS_TIMEOUT = 9;
  static const FY_STATUS_WORKER_FAILED = 10;
  static const FY_STATUS_WRONG_SIZE = 11;
  static const FY_STATUS_PANIC = 12;
  static const FY_STATUS_POISONED = 13;
  static const FY_STATUS_UNSUPPORTED = 14;
  static const FY_STATUS_NO_TEXTURE = 15;
  static const FY_STATUS_DEVICE_LOST = 16;
}

final class FyTexture extends ffi.Opaque {}

final class FyTransform extends ffi.Struct {
  external FyVec3 position;

  external FyQuat rotation;

  external FyVec3 scale;
}

final class FyVec2 extends ffi.Struct {
  @ffi.Float()
  external double x;

  @ffi.Float()
  external double y;

  static ffi.Pointer<FyVec2> $allocate(ffi.Allocator $allocator, {required double x, required double y}) =>
      $allocator<FyVec2>()
        ..ref.x = x
        ..ref.y = y;
}

